!function(e){function r(r){for(var i,d,p=r[0],o=r[1],f=r[2],m=0,c=[];m<p.length;m++)d=p[m],Object.prototype.hasOwnProperty.call(n,d)&&n[d]&&c.push(n[d][0]),n[d]=0;for(i in o)Object.prototype.hasOwnProperty.call(o,i)&&(e[i]=o[i]);for(s&&s(r);c.length;)c.shift()();return a.push.apply(a,f||[]),t()}function t(){for(var e,r=0;r<a.length;r++){for(var t,d=a[r],p=!0,o=1;o<d.length;o++)t=d[o],0!==n[t]&&(p=!1);p&&(a.splice(r--,1),e=i(i.s=d[0]))}return e}function i(r){if(d[r])return d[r].exports;var t=d[r]={i:r,l:!1,exports:{}};return e[r].call(t.exports,t,t.exports,i),t.l=!0,t.exports}var d={},n={69:0},a=[];i.m=e,i.c=d,i.d=function(e,r,t){i.o(e,r)||Object.defineProperty(e,r,{enumerable:!0,get:t})},i.r=function(e){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(e,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(e,"__esModule",{value:!0})},i.t=function(e,r){if(1&r&&(e=i(e)),8&r)return e;if(4&r&&"object"==typeof e&&e&&e.__esModule)return e;var t=Object.create(null);if(i.r(t),Object.defineProperty(t,"default",{enumerable:!0,value:e}),2&r&&"string"!=typeof e)for(var d in e)i.d(t,d,function(r){return e[r]}.bind(null,d));return t},i.n=function(e){var r=e&&e.__esModule?function(){return e.default}:function(){return e};return i.d(r,"a",r),r},i.o=function(e,r){return Object.prototype.hasOwnProperty.call(e,r)},i.p="";var p=window.webpackJsonp=window.webpackJsonp||[],o=p.push.bind(p);p.push=r,p=p.slice();for(var f=0;f<p.length;f++)r(p[f]);var s=o;a.push([134,0]),t()}({134:function(e,r,t){"use strict";t.r(r);var i=t(0);Object(i.a)("de","army",t(135),t(1))},135:function(e){e.exports=JSON.parse('{"category":[{"name":"德国","link":"de_shortcut"},{"name":"陆战武器","link":"de_army"},{"name":"半履带装甲车","link":"de_army#de_army_avhtv"}],"model":"Sdkfz 2型小型半履带车","description":"<p>Sdkfz 2半履带车是德军一种小型牵引车，其形状有些特殊，前部是摩托车结构，后部是履带车结构；该车具有较高车速，机动性强，高速行驶时噪音与振动都较低。</p><p>Sdkfz 2小型半履带车原本是为德军空降兵机动战斗所需而研制，但后来却多用于牵引小型火炮、铺设电话线路及机动通讯等用，后来还在机场作飞机牵引用；至1944年止，Sdkfz 2半履带车一共生产了8300多辆。</p><p>Sdkfz 2小型半履带车于1941年正式装备德军参加入侵苏联的战斗，在苏联的泥泞路与冬季雪路上表现出良好的机动性与可靠性，因此很受德军的欢迎。后来在各个战场上都可见其身影，不少车还被被盟军缴获后化为己用。</p>","part1title":"","part1description":"","part1content":[{"image":"{{text}}Sdkfz 2型小型半履带车四视图（彩图）{{image}}imgs/de/army/de_army_sdkfz2_11.jpg","description":"<h6>Sdkfz 2型小型半履带车</h6><p>Sdkfz 2 小型半履带车长3米，宽1.235米，高1.2米，战斗全重1.56吨；该车的发动机输出最高转速为3400转/分钟，输出功率为36匹马力。最高车速为每小时70公里，越野时速也有50公里，油缸满油时最大行程为250公里。</p><p>Sdkfz 2小型半履带车除前面驾驶员座位外，后座亦可坐2～3人，车后还安装有牵引用的挂钩，可作牵引车用。</p>","caption":""},{"image":"imgs/de/army/de_army_sdkfz2_12.jpg","description":"<p>Sdkfz 2小型半履带车发动机虽然只有36匹马力，但每分钟3400转的高转速使其具有在硬路上每小时70公里的最高车速，该车比摩托车具有更强的越野能力，可在泥泞、深雪、坑洼中顺利行驶，也能涉水而过，在沙漠中能爬上24度的沙坡；该车牵引力虽只有450千克，但常常能牵引更重的火炮与飞机。以至战后，德国仍继续生产了数百部该型车作农业生产用。</p>","caption":""}],"part2title":"战场上的Sdkfz 2型小型半履带车","part2description":"","part2content":[{"image":"imgs/de/army/de_army_sdkfz2_21.jpg","description":"这是一张在德国演习场内拍摄的比较有名的照片，这幅图片出现在1942年7月30日柏林杂志（Berliner Illustrierte）的标题页和第2页，在图中可以看到这辆车后正牵引着一辆拖挂车。","caption":""},{"image":"imgs/de/army/de_army_sdkfz2_22.jpg","description":"1941年冬季，东线苏联战场，一辆德军Sdkfz 2小型摩托履带车在雪地上准备将一门37mm 反坦克炮拖离阵地(也有可能是把这门反坦克火炮刚拖到阵地准备卸下），德军士兵臂上都绑着的红色识别带，这是为了与同样穿着白色冬季伪装服的敌方士兵作出识别。","caption":""},{"image":"imgs/de/army/de_army_sdkfz2_23.jpg","description":"1942年，非洲战场突尼斯，一辆Sdkfz 2小型半履带车正在一辆德军坦克旁边驶过，注意这辆Sdkfz 2小型半履带车的车身侧面固定了一个水罐，这是为了应对非洲干燥的环境所准备的。而且所有在北非作战的Sdkfz 2小型半履带车都会装备一台变速风冷换气扇来对发动机进行冷却。","caption":""},{"image":"imgs/de/army/de_army_sdkfz2_24.jpg","description":"显而易见，用Sdkfz 2小型半履带车来布放野外线路是比较方便的。图中这辆Sdkfz 2小型半履带车上装有重型野外电缆放线滚筒，车后还牵引着一个装有电缆滚筒的拖卡，1名士兵驾驶车行进，2名士兵站在车上进行布线作业。","caption":""},{"image":"imgs/de/army/de_army_sdkfz2_25.jpg","description":"1944年，东线战场，行驶在俄罗斯一条泥泞道路上的德军Sdkfz 2小型摩托履带车，跟在后面的是3辆履带式牵引车。","caption":""},{"image":"imgs/de/army/de_army_sdkfz2_26.jpg","description":"1942/43年间的冬季，在东线苏联战场的Sdkfz 2小型摩托履带车，其时正值冬季，面对苏联境内的崎岖地形和寒冷天气，Sdkfz 2小型摩托履带车仍表现了良好的机动性与可靠性（除开比较脆弱的前叉可靠性有些问题外），证明该车在设计上是成功的。","caption":""},{"image":"imgs/de/army/de_army_sdkfz2_27.jpg","description":"这是1943年拍摄于巴尔干山区的照片，从图中那名德军驾驶员别扭的姿势可以看出，在山路上驾驶Sdkfz 2小型摩托履带车并不是件容易的事，尤其是车后还拖带着一辆（非标准型号）挂车的情况之下。","caption":""},{"image":"imgs/de/army/de_army_sdkfz2_28.jpg","description":"这是德军一辆Sdkfz 2小型半履带车在涉水行驶。可见这种小型半履带车是较适应各种不同的路况的。","caption":""},{"image":"imgs/de/army/de_army_sdkfz2_29.jpg","description":"德军一辆Sdkfz 2小型半履带车准备倒车开上Ju52运输机的机舱，该型车最初就是设计给德军的空降部队用的，因为体积小，可由德国空军的Ju52运输机搭载，与空降兵一起进行空降，以作空降部队的机动运兵和火炮牵引用。","caption":""},{"image":"imgs/de/army/de_army_sdkfz2_30.jpg","description":"德军一辆Sdkfz 2小型半履带车正在机场牵引一架战机到跑道。在二战中后期，为了让空军节省航空燃油，不少Sdkfz 2小型半履带车被配备到机场作牵引飞机用。","caption":""},{"image":"imgs/de/army/de_army_sdkfz2_31.jpg","description":"由于SDkfz 2小型半履带车无任何防护，所以在战斗中极容易被击毁，图中为二战后期一辆被击毁翻倒在地的德军Sdkfz 2小型半履带车，司机也倒地死亡。旁边还有德国人拖儿带女在逃难。","caption":""},{"image":"imgs/de/army/de_army_sdkfz2_32.jpg","description":"盟军对Sdkfz 2这种小型半履带车也很感兴趣，经常将缴获的Sdkfz 2小型半履带车化作已用。图中是盟军使用一辆缴获的德军Sdkfz 2小型半履带车作运输人员和物品用。","caption":""}]}')}});